WITH with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM web_events), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN island_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS island_id_tier, session_id, DATE_TRUNC('YEAR', event_time) AS year_start, COUNT(CASE WHEN page = '/product' THEN 1 END) AS product_count, COUNT(CASE WHEN page = '/product' THEN 1 END) AS product_count_2, MIN(event_time) AS first_seen, COUNT_IF(page = '/product') AS product_events, APPROX_PERCENTILE(session_start_flag, 0.95) AS session_start_flag_p95, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, GROUPING_ID() AS grouping_id FROM sessionized GROUP BY GROUPING SETS ((CASE WHEN island_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END, session_id, DATE_TRUNC('YEAR', event_time)), (CASE WHEN island_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END, session_id), (CASE WHEN island_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END), ())
